-- Append to migration inside a transaction; never retain fixtures.
do $$
declare e uuid:=gen_random_uuid();w uuid:=gen_random_uuid();a uuid:=gen_random_uuid();x uuid:=gen_random_uuid();j uuid:=gen_random_uuid();jp uuid:=gen_random_uuid();application uuid:=gen_random_uuid();work uuid;plan uuid:=gen_random_uuid();request uuid;review uuid;banner uuid:=gen_random_uuid();proof text;tx text:=gen_random_uuid()::text;n integer;
begin
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into auth.users(id,email,raw_user_meta_data) values(e,e||'@growth.invalid','{"account_type":"employer"}'),(w,w||'@growth.invalid','{}'),(a,a||'@growth.invalid','{}'),(x,x||'@growth.invalid','{}');
 update public.profiles set role='admin' where id=a;update public.profiles set employer_premium_until=now()+interval '1 day' where id=e;
 insert into public.jobs(id,employer_id,title,description,category,status) values(j,e,'Completed feedback test','Transactional fixture for completed work feedback','Development','published'),(jp,e,'Paid placement test','Transactional fixture for paid placement controls','Development','published');
 insert into public.applications(id,job_id,applicant_id,cover_note) values(application,j,w,'Application for transactional feedback test');
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);set local role authenticated;work:=public.assign_job_worker(application);
 begin perform public.submit_work_review(work,5,'Too early review');raise exception 'Premature review accepted';exception when raise_exception then if sqlerrm<>'Completed work participant required' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);perform public.update_job_work(work,'start');perform public.update_job_work(work,'submit',100,'Finished');
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);perform public.update_job_work(work,'complete');perform public.submit_work_review(work,5,'Reliable work and clear communication');
 begin perform public.submit_work_review(work,1,'Duplicate review should fail');raise exception 'Duplicate review accepted';exception when unique_violation then null;end;
 perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true);
 begin perform public.submit_work_review(work,5,'Outsider review');raise exception 'Outsider review accepted';exception when raise_exception then if sqlerrm<>'Completed work participant required' then raise;end if;end;
 select count(*) into n from public.work_reviews;if n<>0 then raise exception 'Outsider sees private review metadata';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);perform public.submit_work_review(work,4,'Clear instructions and friendly hirer');reset role;
 select id into review from public.work_reviews where author_id=e and assignment_id=work;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);set local role authenticated;perform public.moderate_work_review(review,true,'Test moderation reason');reset role;
 perform set_config('request.jwt.claims','{"role":"anon"}',true);set local role anon;
 select review_count into n from public.rating_summary(w);if n<>0 then raise exception 'Hidden rating counted publicly';end if;
 select count(*) into n from public.public_work_reviews(e);if n<>1 then raise exception 'Public feedback missing';end if;reset role;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into public.promotion_plans(id,name,daily_price_npr,priority,max_days,active) values(plan,'Fixture tier',100,2,30,true);
 update public.employer_payment_settings set esewa_account_id='fixture-only' where id=1;
 proof:=e::text||'/'||gen_random_uuid()||'.png';insert into storage.objects(bucket_id,name) values('promotion-proofs',proof);
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);set local role authenticated;
 begin perform public.request_job_promotion(jp,plan,1,1,'esewa',tx,proof);raise exception 'Wrong price accepted';exception when raise_exception then if sqlerrm<>'Plan changed; reload before paying' then raise;end if;end;
 request:=public.request_job_promotion(jp,plan,1,100,'esewa',tx,proof);
 if not exists(select 1 from public.job_discovery where id=jp and promotion_rank=2147483647) then raise exception 'Pending proof promoted a job';end if;
 begin perform public.review_job_promotion(request,true);raise exception 'Owner approved own payment';exception when raise_exception then if sqlerrm<>'Admin required' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true);
 select count(*) into n from public.job_promotion_requests where id=request;if n<>0 then raise exception 'Payment history leaked';end if;
 select count(*) into n from storage.objects where bucket_id='promotion-proofs' and name=proof;if n<>0 then raise exception 'Proof leaked';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);perform public.review_job_promotion(request,true,'Exact amount verified in fixture');
 begin perform public.review_job_promotion(request,true);raise exception 'Approval replay extended duration';exception when raise_exception then if sqlerrm<>'Request unavailable' then raise;end if;end;
 if not exists(select 1 from public.job_promotions where job_id=jp and ends_at-starts_at=interval '1 day') then raise exception 'Purchased duration incorrect';end if;reset role;
 perform set_config('request.jwt.claims','{"role":"anon"}',true);set local role anon;
 if not exists(select 1 from public.job_discovery where id=jp and promotion_rank=2) then raise exception 'Active promotion not ranked';end if;reset role;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 begin insert into public.employer_payment_requests(employer_id,payment_method,transaction_code,amount_npr,plan_duration_days,proof_path) values(e,'esewa',upper(tx),100,1,e||'/unused.png');raise exception 'Payment reused across products';exception when unique_violation then null;end;
 update public.job_promotions set starts_at=now()-interval '2 days',ends_at=now()-interval '1 day' where job_id=jp;
 insert into public.sponsor_banners(id,advertiser,title,image_path,target_url,alt_text,placement,active) values(banner,'Fixture brand','Fixture banner','fixture.webp','https://example.com','Fixture image','home',false);
 perform set_config('request.jwt.claims','{"role":"anon"}',true);set local role anon;
 if not exists(select 1 from public.job_discovery where id=jp and promotion_rank=2147483647 and promotion_ends_at is null) then raise exception 'Expired promotion still ranked';end if;
 select count(*) into n from public.sponsor_banners where id=banner;if n<>0 then raise exception 'Draft advertisement public';end if;reset role;
 update public.sponsor_banners set active=true where id=banner;
 set local role anon;select count(*) into n from public.sponsor_banners where id=banner;if n<>1 then raise exception 'Active banner invisible';end if;reset role;
 update public.sponsor_banners set starts_at=now()-interval '2 days',ends_at=now()-interval '1 day' where id=banner;
 set local role anon;select count(*) into n from public.sponsor_banners where id=banner;if n<>0 then raise exception 'Expired banner visible';end if;reset role;
end$$;
rollback;
select 'PASS: completed participants only; duplicate review blocked; private metadata; hidden feedback excluded; exact price; pending payment not promoted; owner cannot approve; private proofs; approval replay blocked; one-day duration; cross-product transaction reuse blocked; automatic expiry; draft and expired banners hidden; fixtures rolled back' as result;
